/*
Layer: Audit (verified identity input).
Reads: embedded fictional crosswalk and authentic manifest.
Writes: warehouse identity_registry and batch_manifest.
Order: after warehouse DDL; before Bronze extraction.
Context: connected warehouse database; sets boa.batch_id for the same session.
*/
BEGIN;
SET LOCAL standard_conforming_strings=on;
SELECT pg_advisory_xact_lock(32113001);
-- statement-break
-- The warehouse accepts only this explicitly verified source-qualified identity registry.
ON CONFLICT (source_system, source_customer_id) DO UPDATE SET enterprise_customer_id=EXCLUDED.enterprise_customer_id, mapping_method=EXCLUDED.mapping_method, verification_status=EXCLUDED.verification_status;
-- statement-break
ON CONFLICT (source_system, source_customer_id) DO UPDATE SET enterprise_customer_id=EXCLUDED.enterprise_customer_id, mapping_method=EXCLUDED.mapping_method, verification_status=EXCLUDED.verification_status;
-- statement-break
-- The authentic input manifest preserves coverage and original JSONL checksums.
ON CONFLICT (batch_id) DO UPDATE SET manifest=EXCLUDED.manifest, input_directory=EXCLUDED.input_directory;
-- statement-break
SELECT set_config('boa.batch_id', 'e54128e8f5f6c03393d5edf6a208058b6260e076a5fc2a059d10fb1562705551', false);
COMMIT;
